<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_role('admin','receptionist'); $title=t('Print patient list');
$doctorId=(int)($_GET['doctor']??0); $date=(string)($_GET['date']??today());
$doctor=one('SELECT * FROM doctors WHERE id=?',[$doctorId]); if(!$doctor || !valid_date($date)) { http_response_code(404); exit(t('Queue not found.')); }
$s=schedule_for($doctorId,$date); $patients=query('SELECT * FROM appointments WHERE doctor_id=? AND appointment_date=? ORDER BY token_number',[$doctorId,$date])->fetchAll();
require dirname(__DIR__).'/includes/header.php';
?>
<main id="main" class="container section print-page"><div class="d-flex justify-content-between align-items-center mb-4 no-print"><a href="<?= e(url('reception/queue.php?doctor='.$doctorId.'&date='.$date)) ?>"><?= e(t('← Back to queue')) ?></a><button class="btn btn-primary" data-print><?= e(t('Print patient list')) ?></button></div><article class="patient-list"><div class="print-heading"><div class="brand"><span class="brand-mark">+</span><span><?= e(t('Doctor Hospital')) ?><small><?= e(t('PATIENT QUEUE LIST')) ?></small></span></div><div><strong><?= e(date_label($date)) ?></strong><small class="d-block"><?= e(t('Pakistan Standard Time')) ?></small></div></div><div class="print-doctor"><h1><?= e($doctor['name']) ?></h1><p><?= e(t('print.doctor',['specialization'=>t($doctor['specialization']),'time'=>$s?time_label($s['consultation_start']):t('Not scheduled')])) ?></p><p><?= e(t('print.summary',['count'=>count($patients)])) ?></p></div><table class="table print-table"><thead><tr><th><?= e(t('Token')) ?></th><th><?= e(t('Patient name')) ?></th><th><?= e(t('Mobile number')) ?></th><th><?= e(t('Estimated time')) ?></th><th><?= e(t('Status')) ?></th></tr></thead><tbody><?php foreach($patients as $p): ?><tr><td><strong>#<?= e($p['token_number']) ?></strong></td><td><?= e($p['patient_name']) ?></td><td dir="ltr"><?= e($p['patient_phone']) ?></td><td><?= e(time_label($p['estimated_time'])) ?></td><td><?= e(t($p['status'])) ?></td></tr><?php endforeach; ?><?php if(!$patients): ?><tr><td colspan="5"><?= e(t('No appointments for this date.')) ?></td></tr><?php endif; ?></tbody></table><p class="print-footnote"><?= e(t('Consultation times are estimates. Cancelled tokens are retained for reference. Keep this patient list confidential.')) ?><br><?= e(t('print.timestamp',['time'=>date_label(today()).'، '.time_label(date('H:i:s'))])) ?></p></article></main><?php require dirname(__DIR__).'/includes/footer.php'; ?>
